sys_script_include.script:
var TrainingUtilsForm = Class.create();
TrainingUtilsForm.prototype = {
    initialize: function() {},

    getCoursesByScheduleDate: function(scheduleDateSysId) {
        var courses = [];

        if (!scheduleDateSysId) {
            return 'sys_idINnone'; 
        }

        var gr = new GlideRecord('x_1567520_shark_0_training_schedule'); 
        if (!gr.get(scheduleDateSysId)) {
            return 'sys_idINnone'; 
        }

        var scheduleDate = gr.schedule_date; 

        gr = new GlideRecord('x_1567520_shark_0_training_schedule');
        gr.addQuery('schedule_date', scheduleDate);  
        gr.query();

        while (gr.next()) {
            if (gr.course) {
                courses.push(gr.course.sys_id.toString()); 
            }
        }

        if (courses.length > 0) {
            return 'sys_idIN' + courses.join(','); 
        } else {
            return 'sys_idINnone'; 
        }
    },

    type: 'TrainingUtilsForm'
};
